@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class ScratchBrowserTest extends AbstractBasePlaywrightIT {

    @LocalServerPort
    int port;

    @Autowired
    QueryLog queryLog;

    @Test
    void scratch() throws Exception {
        String base = "http://localhost:" + port + "/";
        page.navigate(base + "?name=vir&status=ACTIVE,CLOSED");
        page.waitForLoadState();
        page.waitForSelector("#customer-count");
        System.out.println("SCRATCH initial url=" + page.url() + " summary=" + page.locator("#customer-count").textContent()
                + " name=" + page.locator("vaadin-text-field").first().inputValue());

        page.navigate(base);
        page.waitForSelector("#customer-count");
        page.waitForTimeout(500);
        System.out.println("SCRATCH bare url=" + page.url() + " summary=" + page.locator("#customer-count").textContent());

        int historyBefore = ((Number) page.evaluate("history.length")).intValue();
        queryLog.clear();
        var name = page.locator("vaadin-text-field").first().locator("input");
        name.click();
        name.pressSequentially("josephine", new Locator.PressSequentiallyOptions().setDelay(30));
        page.waitForTimeout(1500);
        int historyAfter = ((Number) page.evaluate("history.length")).intValue();
        System.out.println("SCRATCH typed url=" + page.url() + " summary=" + page.locator("#customer-count").textContent());
        System.out.println("SCRATCH history before=" + historyBefore + " after=" + historyAfter);
        System.out.println("SCRATCH pageQueries=" + queryLog.pageQueries() + " countQueries=" + queryLog.countQueries());

        queryLog.clear();
        page.locator("vaadin-multi-select-combo-box").first().click();
        page.waitForTimeout(500);
        page.keyboard().press("Escape");
        page.waitForTimeout(500);
        System.out.println("SCRATCH after status open url=" + page.url() + " pageQ=" + queryLog.pageQueries().size() + " countQ=" + queryLog.countQueries());
    }
}
