+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * Which customers a query should return.
+ *
+ * <p>The name is split on whitespace into terms, and every term must appear as a
+ * substring of the customer's first name or last name. Matching ignores case and
+ * accents. An empty name matches everyone.
+ *
+ * <p>An empty set of statuses matches every status; otherwise the customer's
+ * status must be one of the given statuses.
+ *
+ * @param name     the text typed into the name filter; may be blank
+ * @param statuses the statuses to show; empty means all of them
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = (statuses == null) ? Set.of() : Set.copyOf(statuses);
+    }
+
+    /** Returns {@code true} if {@code customer} satisfies both the name and the status filter. */
+    public boolean matches(Customer customer) {
+        return matchesName(customer) && matchesStatus(customer);
+    }
+
+    private boolean matchesName(Customer customer) {
+        List<String> terms = nameTerms();
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String first = normalize(customer.firstName());
+        String last = normalize(customer.lastName());
+        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+    }
+
+    private boolean matchesStatus(Customer customer) {
+        return statuses.isEmpty() || statuses.contains(customer.status());
+    }
+
+    private List<String> nameTerms() {
+        String normalized = normalize(name).strip();
+        if (normalized.isEmpty()) {
+            return List.of();
+        }
+        return List.of(normalized.split("\\s+"));
+    }
+
+    /** Lower-cases the text and strips accents, so that {@code Mäkinen} becomes {@code makinen}. */
+    static String normalize(String text) {
+        return Normalizer.normalize(text, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
